SELECT cp.cp_department, cd.cd_gender, hd.hd_buy_potential, SUM(cs.cs_net_paid) AS total_net_paid, COUNT(DISTINCT cs.cs_order_number) AS order_cnt FROM catalog_sales cs JOIN catalog_page cp ON cs.cs_catalog_page_sk = cp.cp_catalog_page_sk JOIN customer_demographics cd ON cs.cs_bill_cdemo_sk = cd.cd_demo_sk JOIN household_demographics hd ON cs.cs_bill_hdemo_sk = hd.hd_demo_sk WHERE cp.cp_start_date_sk = 2451088 AND cd.cd_credit_rating = 'Good      ' AND hd.hd_income_band_sk = 11 AND EXISTS (SELECT 1 FROM catalog_page cp2 WHERE cp2.cp_catalog_page_sk = cs.cs_catalog_page_sk AND cp2.cp_type = 'quarterly') GROUP BY cp.cp_department, cd.cd_gender, hd.hd_buy_potential HAVING SUM(cs.cs_net_paid) > 962.52
